1	import React, { useState, useCallback, useEffect, useMemo } from "react";
2	import { useSearchParams, useLocation } from "react-router-dom";
3	import { useAuth } from "@/hooks/useAuth";
4	import { supabase } from "@/integrations/supabase/client";
5	import AppHeader from "@/components/AppHeader";
6	import AuthDialog from "@/components/AuthDialog";
7	import JobSidebar from "@/components/JobSidebar";
8	import JobDetailView from "@/components/JobDetailView";
9	import JobsOverviewCard from "@/components/JobsOverviewCard";
10	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
11	import { Card, CardContent } from "@/components/ui/card";
12	import { Badge } from "@/components/ui/badge";
13	import { Button } from "@/components/ui/button";
14	import { Plus, Briefcase, FileText, Coins, CheckCircle2, ChevronRight, ChevronLeft } from "lucide-react";
15	import { format } from "date-fns";
16	import { toast } from "sonner";
17	
18	export interface PastJob {
19	  id: string;
20	  title: string | null;
21	  job_description: string;
22	  status: string;
23	  created_at: string;
24	  resume_count: number;
25	  jd_analysis_json: any;
26	  dynamic_weights_json: Record<string, number> | null;
27	  inbox_email: string | null;
28	}
29	
30	export interface Result {
31	  id: string;
32	  resume_id: string;
33	  overall_score: number;
34	  missing_skills: string[];
35	  summary: string | null;
36	  interview_questions: any;
37	  filename: string;
38	  file_path: string | null;
39	  candidate_name: string | null;
40	  candidate_email?: string | null;
41	  candidate_phone?: string | null;
42	  candidate_location?: string | null;
43	  // Dynamic scoring fields
44	  hard_fit?: boolean;
45	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
46	  confidence?: number;
47	  strengths_json?: string[];
48	  gaps_json?: string[];
49	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
50	  matched_must_haves?: string[];
51	  missing_must_haves?: string[];
52	  scoring_version?: string;
53	  pending?: boolean;
54	  parsed_json?: any;
55	}
56	
57	export interface ExistingResume {
58	  id: string;
59	  filename: string;
60	  file_path: string | null;
61	  candidate_name: string | null;
62	  created_at: string;
63	}
64	
65	type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";
66	
67	const Index = () => {
68	  const { user, profile } = useAuth();
69	  const [searchParams, setSearchParams] = useSearchParams();
70	  const location = useLocation();
71	
72	  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
73	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
74	  const [view, setView] = useState<ViewMode>(location.pathname === "/jobs" ? "my-jobs" : "dashboard");
75	  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
76	  const [results, setResults] = useState<Result[]>([]);
77	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
78	  const [authOpen, setAuthOpen] = useState(false);
79	
80	  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);
81	
82	  const fetchPastJobs = useCallback(async () => {
83	    if (!user) return;
84	    setLoadingPastJobs(true);
85	    try {
86	      const { data: jobs } = await supabase
87	        .from("jobs")
88	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
89	        .eq("user_id", user.id)
90	        .order("created_at", { ascending: false })
91	        .limit(50);
92	      if (jobs) {
93	        setPastJobs(jobs.map((j: any) => ({
94	          id: j.id,
95	          title: j.title,
96	          job_description: j.job_description,
97	          status: j.status,
98	          created_at: j.created_at,
99	          resume_count: j.resumes?.[0]?.count ?? 0,
100	          jd_analysis_json: j.jd_analysis_json,
101	          dynamic_weights_json: j.dynamic_weights_json,
102	          inbox_email: j.inbox_email ?? null,
103	        })));
104	      }
105	    } catch (err) {
106	      toast.error("Failed to load jobs");
107	    } finally {
108	      setLoadingPastJobs(false);
109	    }
110	  }, [user]);
111	
112	  useEffect(() => {
113	    fetchPastJobs();
114	  }, [fetchPastJobs]);
115	
116	  // Sync view with route path
117	  useEffect(() => {
118	    if (location.pathname === "/jobs") {
119	      setView("my-jobs");
120	      setSelectedJobId(null);
121	    }
122	  }, [location.pathname]);
123	
124	  // Handle URL params for deep linking
125	  useEffect(() => {
126	    const jobParam = searchParams.get("job");
127	    const newParam = searchParams.get("new");
128	
129	    if (jobParam && user) {
130	      loadJobData(jobParam);
131	      setSearchParams({}, { replace: true });
132	    } else if (newParam && user) {
133	      handleNewJob();
134	      setSearchParams({}, { replace: true });
135	    }
136	    // eslint-disable-next-line react-hooks/exhaustive-deps
137	  }, [searchParams, user]);
138	
139	  const loadJobData = async (jobId: string) => {
140	    setSelectedJobId(jobId);
141	    setView("job-detail");
142	    try {
143	      // Single query for all resume data (was 2 separate queries)
144	      const { data: allResumes } = await supabase
145	        .from("resumes")
146	        .select("id, filename, file_path, candidate_name, created_at, parsed_json")
147	        .eq("job_id", jobId)
148	        .order("created_at", { ascending: false });
149	
150	      const resumeData = allResumes ?? [];
151	      setExistingResumes(resumeData.map((r) => ({
152	        id: r.id, filename: r.filename, file_path: r.file_path,
153	        candidate_name: r.candidate_name, created_at: r.created_at,
154	      })));
155	
156	      if (resumeData.length === 0) {
157	        setResults([]);
158	        return;
159	      }
160	
161	      const resumeIds = resumeData.map((r) => r.id);
162	      const { data: resultData } = await supabase
163	        .from("results")
164	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
165	        .in("resume_id", resumeIds);
166	
167	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
168	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
169	        const resume = resumeMap.get(r.resume_id);
170	        const parsed = resume?.parsed_json as any;
171	        return {
172	          ...r,
173	          overall_score: r.overall_score ?? 0,
174	          missing_skills: r.missing_skills ?? [],
175	          filename: resume?.filename ?? "Unknown",
176	          file_path: resume?.file_path ?? null,
177	          candidate_name: resume?.candidate_name ?? null,
178	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
179	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
180	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
181	          parsed_json: resume?.parsed_json ?? null,
182	        };
183	      });
184	      // Deduplicate by resume_id — keep highest scoring result per resume
185	      const deduped = new Map<string, Result>();
186	      for (const r of allMerged) {
187	        const existing = deduped.get(r.resume_id);
188	        if (!existing || r.overall_score > existing.overall_score) {
189	          deduped.set(r.resume_id, r);
190	        }
191	      }
192	      const merged = Array.from(deduped.values());
193	      merged.sort((a, b) => b.overall_score - a.overall_score);
194	      setResults(merged);
195	    } catch (err) {
196	      toast.error("Failed to load job data");
197	    }
198	  };
199	
200	  const handleNewJob = () => {
201	    setSelectedJobId(null);
202	    setView("new-job");
203	    setResults([]);
204	    setExistingResumes([]);
205	  };
206	
207	  const handleGoToDashboard = () => {
208	    setSelectedJobId(null);
209	    setView("dashboard");
210	    setResults([]);
211	    setExistingResumes([]);
212	  };
213	
214	  const handleGoToMyJobs = () => {
215	    setSelectedJobId(null);
216	    setView("my-jobs");
217	    setResults([]);
218	    setExistingResumes([]);
219	  };
220	
221	  const handleJobCreated = (job: PastJob) => {
222	    setPastJobs((prev) => [job, ...prev]);
223	    setSelectedJobId(job.id);
224	    loadJobData(job.id);
225	  };
226	
227	  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
228	    setPastJobs((prev) =>
229	      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
230	    );
231	  };
232	
233	  const handleDeleteJobs = async (jobIds: string[]) => {
234	    await supabase.from("jobs").delete().in("id", jobIds);
235	    setPastJobs((prev) => prev.filter((j) => !jobIds.includes(j.id)));
236	  };
237	
238	  const requireAuth = useCallback(() => {
239	    if (!user) { setAuthOpen(true); return true; }
240	    return false;
241	  }, [user]);
242	
243	  return (
244	    <SidebarProvider className="h-svh overflow-hidden">
245	      <JobSidebar
246	        showDashboard={view === "dashboard"}
247	        showMyJobs={view === "my-jobs" || view === "job-detail"}
248	        onNewJob={handleNewJob}
249	        onDashboard={handleGoToDashboard}
250	        onMyJobs={handleGoToMyJobs}
251	        onAuthRequired={() => setAuthOpen(true)}
252	        isAuthenticated={!!user}
253	      />
254	
255	      <SidebarInset className="h-svh overflow-y-auto">
256	        <AppHeader />
257	        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
258	          <SidebarTrigger />
259	          <span className="ml-2 text-sm font-medium text-muted-foreground">Menu</span>
260	        </div>
261	
262	        {/* Dashboard view */}
263	        {view === "dashboard" && user ? (
264	          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
265	            {/* Hero Section — Greeting + Create Button */}
266	            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
267	              <div>
268	                <h1 className="text-2xl font-bold text-foreground">
269	                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
270	                </h1>
271	                <p className="text-sm text-muted-foreground mt-1">
272	                  Here's an overview of your hiring activity and insights.
273	                </p>
274	              </div>
275	              <Button size="lg" className="gap-2 shadow-md px-6" onClick={handleNewJob}>
276	                <Plus className="h-4 w-4" /> Create Job
277	              </Button>
278	            </div>
279	
280	            {/* Stats Cards */}
281	            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
282	              {[
283	                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
284	                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
285	                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
286	                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
287	              ].map((s) => (
288	                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
289	                  <CardContent className="px-5 py-4 flex items-center gap-4">
290	                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
291	                      <s.icon className="h-5 w-5" />
292	                    </div>
293	                    <div>
294	                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
295	                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
296	                    </div>
297	                  </CardContent>
298	                </Card>
299	              ))}
300	            </div>
301	
302	            {/* Recent Jobs */}
303	            {pastJobs.length > 0 && (
304	              <div className="space-y-3">
305	                <div className="flex items-center justify-between">
306	                  <h2 className="text-sm font-semibold text-foreground">Recent Jobs</h2>
307	                  <button onClick={handleGoToMyJobs} className="text-xs font-medium text-primary hover:text-primary/80 transition-colors">
308	                    View All Jobs →
309	                  </button>
310	                </div>
311	                <div className="grid gap-3">
312	                  {pastJobs.slice(0, 5).map((job) => (
313	                    <Card key={job.id} className="cursor-pointer hover:shadow-md transition-all border border-border/60" onClick={() => loadJobData(job.id)}>
314	                      <CardContent className="px-5 py-3.5 flex items-center justify-between">
315	                        <div className="flex items-center gap-3 min-w-0">
316	                          <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
317	                            <Briefcase className="h-4 w-4 text-primary" />
318	                          </div>
319	                          <div className="min-w-0">
320	                            <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
321	                            <p className="text-xs text-muted-foreground mt-0.5">
322	                              {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
323	                            </p>
324	                          </div>
325	                        </div>
326	                        <div className="flex items-center gap-3 shrink-0">
327	                          <Badge
328	                            variant={job.status === "completed" ? "success" : job.status === "pending" || job.status === "processing" ? "warning" : "outline"}
329	                            className="text-xs"
330	                          >
331	                            {job.status.charAt(0).toUpperCase() + job.status.slice(1)}
332	                          </Badge>
333	                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
334	                        </div>
335	                      </CardContent>
336	                    </Card>
337	                  ))}
338	                </div>
339	              </div>
340	            )}
341	
342	            {/* Getting started guide — show only for new users */}
343	            {pastJobs.length === 0 && !loadingPastJobs && (
344	              <Card>
345	                <CardContent className="px-5 py-4 space-y-3">
346	                  <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
347	                  <div className="space-y-2.5">
348	                    {[
349	                      { step: "1", text: "Click \"Create New Job\" and paste a job description" },
350	                      { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
351	                      { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
352	                    ].map((item) => (
353	                      <div key={item.step} className="flex items-start gap-3 text-sm">
354	                        <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
355	                        <span className="text-muted-foreground">{item.text}</span>
356	                      </div>
357	                    ))}
358	                  </div>
359	                </CardContent>
360	              </Card>
361	            )}
362	          </div>
363	        ) : view === "my-jobs" && user ? (
364	          /* My Jobs view — full management */
365	          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
366	            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
367	              <div className="space-y-1">
368	                <button
369	                  onClick={handleGoToDashboard}
370	                  className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors group mb-1"
371	                >
372	                  <ChevronLeft className="h-3 w-3 group-hover:-translate-x-0.5 transition-transform duration-150" />
373	                  Dashboard
374	                </button>
375	                <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
376	                <p className="text-sm text-muted-foreground">Manage all your job postings.</p>
377	              </div>
378	              <Button size="lg" className="gap-2 shadow-md px-6 shrink-0" onClick={handleNewJob}>
379	                <Plus className="h-4 w-4" /> Create Job
380	              </Button>
381	            </div>
382	            <JobsOverviewCard jobs={pastJobs} loading={loadingPastJobs} onSelectJob={loadJobData} onDeleteJobs={handleDeleteJobs} />
383	          </div>
384	        ) : (
385	          <JobDetailView
386	            selectedJobId={selectedJobId}
387	            selectedJob={selectedJob}
388	            results={results}
389	            setResults={setResults}
390	            existingResumes={existingResumes}
391	            setExistingResumes={setExistingResumes}
392	            onJobCreated={handleJobCreated}
393	            onAuthRequired={() => setAuthOpen(true)}
394	            isAuthenticated={!!user}
395	            pastJobs={pastJobs}
396	            onJobUpdated={handleJobUpdated}
397	            onBack={handleGoToMyJobs}
398	          />
399	        )}
400	      </SidebarInset>
401	
402	      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
403	    </SidebarProvider>
404	  );
405	};
406	
407	export default Index;
408	
